#include "api.cpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("xbox-native ISO [FRAMES] [PPM]");rrDiscFile.open(argv[1],std::ios::binary);rrDiscFile.seekg(0,std::ios::end);if(!rr_init_file(rrDiscFile.tellg()))throw std::runtime_error(rr_error());
if(auto file=std::getenv("RR_LOAD")){std::ifstream f(file,std::ios::binary);std::vector<uint8_t>s((std::istreambuf_iterator<char>(f)),{});memcpy(rr_state_input(s.size()),s.data(),s.size());if(!rr_state_load(s.size()))throw std::runtime_error("State load failed");}
auto end=frames+(argc>2?std::stoull(argv[2]):1);auto start=go_time_Now();auto maxSteps=std::getenv("RR_MAX_STEPS")?std::stoull(std::getenv("RR_MAX_STEPS")):UINT64_MAX;while(frames<end&&machine->CPU->Steps<maxSteps){if(rr_run(10000)<0)throw std::runtime_error(rr_error());}if(std::getenv("RR_LOG"))for(auto s:machine->Log)std::cerr<<s<<"\n";std::cout<<rr_proof()<<"\n"<<rr_profile()<<"\n";std::cerr<<"Seconds "<<(go_time_Now()-start)/1e9<<"\n";
if(auto file=std::getenv("RR_SAVE")){auto n=rr_state_save();if(!n)throw std::runtime_error("State save failed");std::ofstream f(file,std::ios::binary);f.write((char*)rr_state_data(),n);}
if(argc>3){auto s=rrSurface(machine);auto*p=rr_frame();std::ofstream f(argv[3],std::ios::binary);f<<"P6\n"<<s.w<<" "<<s.h<<"\n255\n";for(int i=0;i<s.w*s.h;i++)f.write((char*)p+i*4,3);}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
